CivicStaticDataStruct* CivicParser::parse_data_dependencies () {
    CivicStaticDataStruct* parsed_data = new CivicStaticDataStruct[m_item_count]();
    for (u32 i = 0; i < m_item_count; ++i) {
        StringManager line_items;
        get_line_items(get_raw_lines().get_string_content(i), line_items);
        parsed_data[i].type = parse_civic_type(line_items, 1);
        parsed_data[i].reqs = parse_item_reqs(line_items, 2);
        parsed_data[i].effects = parse_item_effects_optional(line_items, 3);
    }
    return parsed_data;
}

